InvokeScript:
Write-WinUtilHost 'Attempting to remove Microsoft Edge (best-effort, where supported)...'
Write-WinUtilLog -Level 'INFO' -Component 'RemoveEdge' -Message 'Starting Microsoft Edge removal attempt.'

$removed = $false
$attempts = @()

try {
  if (Get-Command winget -ErrorAction SilentlyContinue) {
    $p = Start-Process -FilePath 'winget' -ArgumentList 'uninstall --id Microsoft.Edge --silent --accept-source-agreements --disable-interactivity' -Wait -PassThru -NoNewWindow -ErrorAction SilentlyContinue
    if ($p -and $p.ExitCode -eq 0) { $removed = $true; $attempts += 'winget-uninstall:success' } else { $attempts += "winget-uninstall:exit=$($p.ExitCode 2>$null)" }
  }
} catch { $attempts += "winget-uninstall:error=$($_.Exception.Message)" }

try {
  $roots = @("$Env:ProgramFiles (x86)\Microsoft\Edge\Application", "$Env:ProgramFiles\Microsoft\Edge\Application")
  $setupPath = $null
  foreach ($root in $roots) {
    if (-not $setupPath -and (Test-Path -LiteralPath $root -ErrorAction SilentlyContinue)) {
      $setupPath = Get-ChildItem -Path (Join-Path $root '*\Installer\setup.exe') -File -ErrorAction SilentlyContinue | Sort-Object FullName -Descending | Select-Object -First 1 -ExpandProperty FullName
    }
  }
  $systemAppsRoot = "$Env:SystemRoot\SystemApps"
  $edgeSystemAppDir = $null
  if (Test-Path -LiteralPath $systemAppsRoot -ErrorAction SilentlyContinue) {
    $edgeSystemAppDir = Get-ChildItem -Path $systemAppsRoot -Directory -Filter 'Microsoft.MicrosoftEdge_*' -ErrorAction SilentlyContinue | Sort-Object FullName -Descending | Select-Object -First 1 -ExpandProperty FullName
  }
  if ($setupPath -and $edgeSystemAppDir) {
    $dummyEdgePath = Join-Path $edgeSystemAppDir 'MicrosoftEdge.exe'
    try { New-Item -Path $dummyEdgePath -ItemType File -Force -ErrorAction Stop | Out-Null } catch {}
    $proc = Start-Process -FilePath $setupPath -ArgumentList '--uninstall --system-level --force-uninstall' -Wait -PassThru -NoNewWindow -ErrorAction SilentlyContinue
    if ($proc -and $proc.ExitCode -eq 0) { $removed = $true; $attempts += 'legacy-setup:success' } else { $attempts += "legacy-setup:exit=$($proc.ExitCode 2>$null)" }
  } else {
    $attempts += 'legacy-setup:unavailable'
  }
} catch { $attempts += "legacy-setup:error=$($_.Exception.Message)" }

try {
  $edgePkgs = Get-AppxPackage -AllUsers -Name '*MicrosoftEdge*','*Microsoft.MicrosoftEdge*' -ErrorAction SilentlyContinue | Where-Object { $_.Name -notmatch 'WebView2' }
  foreach ($pkg in @($edgePkgs)) {
    try { Remove-AppxPackage -Package $pkg.PackageFullName -AllUsers -ErrorAction Stop; $removed = $true; $attempts += "appx:$($pkg.Name):removed" } catch { $attempts += "appx:$($pkg.Name):failed" }
  }
  $prov = Get-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -like '*MicrosoftEdge*' -and $_.DisplayName -notlike '*WebView2*' }
  foreach ($pp in @($prov)) {
    try { Remove-AppxProvisionedPackage -Online -PackageName $pp.PackageName -ErrorAction Stop | Out-Null; $removed = $true; $attempts += "prov:$($pp.DisplayName):removed" } catch { $attempts += "prov:$($pp.DisplayName):failed" }
  }
} catch { $attempts += "appx/provisioned:error=$($_.Exception.Message)" }

Write-WinUtilLog -Level 'INFO' -Component 'RemoveEdge' -Message ("Edge removal attempts: " + ($attempts -join '; '))
if ($removed) {
  Write-WinUtilHost 'Microsoft Edge removal steps completed where supported. A restart may be required and some Windows components may restore Edge.'
  Write-WinUtilLog -Level 'INFO' -Component 'RemoveEdge' -Message 'Microsoft Edge removal completed (best-effort).'
  return
}

$msg = 'Microsoft Edge could not be removed by supported automated methods on this Windows version/build (common on modern Windows 10/11 where Edge is system-protected). No unsupported system changes were made.'
Write-WinUtilHost $msg
Write-WinUtilLog -Level 'WARN' -Component 'RemoveEdge' -Message $msg

