try {
  if (Get-Command winget -ErrorAction SilentlyContinue) {
    $p = Start-Process -FilePath 'winget' -ArgumentList 'install --id Microsoft.Edge --source winget --accept-package-agreements --accept-source-agreements --silent --disable-interactivity' -Wait -PassThru -NoNewWindow -ErrorAction SilentlyContinue
