try {
  if (-not $installed -and (Get-Command choco -ErrorAction SilentlyContinue)) {
    $p = Start-Process -FilePath 'choco' -ArgumentList 'install microsoft-edge -y --no-progress' -Wait -PassThru -NoNewWindow -ErrorAction SilentlyContinue
    if ($p -and $p.ExitCode -eq 0) { $installed = $true } else { $errors += "choco exit $($p.ExitCode 2>$null)" }
