if ($installed) {
  Write-WinUtilHost 'Microsoft Edge install/restore command completed. A restart or sign-in may be required.'
  Write-WinUtilLog -Level 'INFO' -Component 'RemoveEdge' -Message 'Microsoft Edge install/restore command completed.'
  return
}
$msg = 'Automatic Edge reinstall did not complete (winget/choco unavailable or failed). Download and reinstall Edge manually from https://www.microsoft.com/edge if needed.'
if ($errors.Count -gt 0) { $msg += " Details: $($errors -join '; ')" }
Write-WinUtilHost $msg
Write-WinUtilLog -Level 'WARN' -Component 'RemoveEdge' -Message $msg

