if (-not (Get-Command Get-BitLockerVolume -ErrorAction SilentlyContinue)) {
    Write-WinUtilHost 'BitLocker is not available on this system.'
    Write-WinUtilLog -Level 'WARN' -Component 'DisableBitLocker' -Message 'BitLocker is not available on this system.'
    return
