try {
    $bitLockerVolume = Get-BitLockerVolume -MountPoint $Env:SystemDrive -ErrorAction Stop

    if ($bitLockerVolume.VolumeStatus -eq 'FullyDecrypted') {
        Write-WinUtilHost \"BitLocker is already disabled on $($Env:SystemDrive).\"
        Write-WinUtilLog -Level 'INFO' -Component 'DisableBitLocker' -Message \"BitLocker is already disabled on $($Env:SystemDrive)\"
    } else {
        Disable-BitLocker -MountPoint $Env:SystemDrive -ErrorAction Stop
        Write-WinUtilHost \"BitLocker has been disabled on $($Env:SystemDrive).\"
        Write-WinUtilLog -Level 'INFO' -Component 'DisableBitLocker' -Message \"BitLocker disabled on $($Env:SystemDrive)\"
    }
} catch {
    Write-WinUtilLog -Level 'ERROR' -Component 'DisableBitLocker' -Message \"Failed to disable BitLocker: $($_.Exception.Message)\"
    Write-WinUtilHost 'Failed to disable BitLocker.'
    throw
}

