InvokeScript:
$OneDrivePath = $Env:OneDrive
$OneDriveFolderExists = -not [string]::IsNullOrWhiteSpace($OneDrivePath) -and (Test-Path -LiteralPath $OneDrivePath -PathType Container -ErrorAction SilentlyContinue)

$OneDriveAcl = $null
if ($OneDriveFolderExists) {
  try { $OneDriveAcl = Get-Acl -LiteralPath $OneDrivePath -ErrorAction Stop } catch {
    Write-WinUtilLog -Level 'WARN' -Component 'RemoveOneDrive' -Message "Failed to capture OneDrive ACL: $($_.Exception.Message)"
    Write-WinUtilHost 'Failed to capture OneDrive folder permissions; continuing best-effort.'
  }
} else {
  Write-WinUtilHost 'OneDrive folder is not present for this profile; proceeding with best-effort uninstall/cleanup.'
  Write-WinUtilLog -Level 'INFO' -Component 'RemoveOneDrive' -Message 'OneDrive folder absent for current profile.'
}

$uninstalled = $false
try {
  if ($OneDriveFolderExists) {
    try { icacls "$OneDrivePath" /deny "*S-1-5-32-544:(D,DC)" /T /C | Out-Null } catch { Write-WinUtilLog -Level 'WARN' -Component 'RemoveOneDrive' -Message "Unable to protect OneDrive folder: $($_.Exception.Message)" }
  }

  Write-WinUtilHost 'Uninstalling OneDrive (best-effort)...'
  $setupCandidates = @(
    "$Env:SystemRootSystem32OneDriveSetup.exe",
    "$Env:SystemRootSysWOW64OneDriveSetup.exe"
  ) | Where-Object { $_ -and (Test-Path -LiteralPath $_ -ErrorAction SilentlyContinue) }
  foreach ($setup in $setupCandidates) {
    try {
      $p = Start-Process -FilePath $setup -ArgumentList '/uninstall' -Wait -PassThru -NoNewWindow -ErrorAction Stop
      if ($p -and ($p.ExitCode -eq 0 -or $uninstalled -eq $false)) { $uninstalled = $true }
      Write-WinUtilLog -Level 'INFO' -Component 'RemoveOneDrive' -Message "Ran OneDrive setup uninstall: $setup (exit $($p.ExitCode))"
    } catch {
      Write-WinUtilLog -Level 'WARN' -Component 'RemoveOneDrive' -Message "OneDrive setup uninstall failed for $setup: $($_.Exception.Message)"
    }
  }

  # Fallback: winget uninstall if available
  if (-not $uninstalled -and (Get-Command winget -ErrorAction SilentlyContinue)) {
    try {
      $p = Start-Process -FilePath 'winget' -ArgumentList 'uninstall --id Microsoft.OneDrive --silent --accept-source-agreements --disable-interactivity' -Wait -PassThru -NoNewWindow -ErrorAction SilentlyContinue
      if ($p -and $p.ExitCode -eq 0) { $uninstalled = $true }
      Write-WinUtilLog -Level 'INFO' -Component 'RemoveOneDrive' -Message "winget OneDrive uninstall exit: $($p.ExitCode 2>$null)"
    } catch { Write-WinUtilLog -Level 'WARN' -Component 'RemoveOneDrive' -Message "winget OneDrive uninstall failed: $($_.Exception.Message)" }
  }

  # Stop related processes best-effort
  foreach ($name in @('OneDrive','FileCoAuth','OneDriveStandaloneUpdater')) {
    try { Get-Process -Name $name -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue } catch {}
  }

  $OneDriveLeftovers = @("$Env:LocalAppDataMicrosoftOneDrive", "$Env:ProgramDataMicrosoft OneDrive", "$Env:SystemDriveOneDriveTemp")
  foreach ($LeftoverPath in $OneDriveLeftovers) {
    try {
      if (Test-Path -LiteralPath $LeftoverPath -ErrorAction SilentlyContinue) {
        Remove-Item -LiteralPath $LeftoverPath -Recurse -Force -ErrorAction SilentlyContinue
      }
    } catch { Write-WinUtilLog -Level 'WARN' -Component 'RemoveOneDrive' -Message "Failed to remove leftover path $LeftoverPath: $($_.Exception.Message)" }
  }

  # OneSyncSvc template may not exist on all Windows 10/11 installations
  try {
    if (Test-Path -LiteralPath 'HKLM:SYSTEMCurrentControlSetServicesOneSyncSvc') {
      Set-Service -Name OneSyncSvc -StartupType Disabled -ErrorAction SilentlyContinue
    }
  } catch { Write-WinUtilLog -Level 'WARN' -Component 'RemoveOneDrive' -Message "Unable to disable OneSyncSvc: $($_.Exception.Message)" }

  if ($uninstalled) {
    Write-WinUtilHost 'OneDrive uninstall steps completed (best-effort).'
    Write-WinUtilLog -Level 'INFO' -Component 'RemoveOneDrive' -Message 'OneDrive uninstall steps completed.'
  } else {
    Write-WinUtilHost 'OneDrive uninstall could not be fully confirmed on this system; remaining cleanup was attempted best-effort.'
    Write-WinUtilLog -Level 'WARN' -Component 'RemoveOneDrive' -Message 'OneDrive uninstall not fully confirmed; cleanup attempted best-effort.'
  }
} catch {
  Write-WinUtilLog -Level 'ERROR' -Component 'RemoveOneDrive' -Message "OneDrive removal encountered an error: $($_.Exception.Message)"
  throw
} finally {
  if ($OneDriveFolderExists -and $OneDriveAcl) {
    try { Set-Acl -LiteralPath $OneDrivePath -AclObject $OneDriveAcl -ErrorAction Stop } catch { Write-WinUtilLog -Level 'WARN' -Component 'RemoveOneDrive' -Message "Failed to restore OneDrive ACL: $($_.Exception.Message)" }
  }
}

if ($OneDriveFolderExists -and (Test-Path -LiteralPath $OneDrivePath -PathType Container -ErrorAction SilentlyContinue)) {
  try {
    $items = @(Get-ChildItem -LiteralPath $OneDrivePath -Force -ErrorAction SilentlyContinue)
    if ($items.Count -eq 0) {
      Remove-Item -LiteralPath $OneDrivePath -Force -ErrorAction SilentlyContinue
      try { [Environment]::SetEnvironmentVariable('OneDrive', $null, 'User') } catch {}
    } else {
      Write-WinUtilLog -Level 'INFO' -Component 'RemoveOneDrive' -Message 'OneDrive folder not removed because it is not empty (user files preserved).'
    }
  } catch { Write-WinUtilLog -Level 'WARN' -Component 'RemoveOneDrive' -Message "OneDrive folder cleanup check failed: $($_.Exception.Message)" }
}

