$osBuild = 0
try { $osBuild = [int](Get-CimInstance Win32_OperatingSystem -ErrorAction Stop).BuildNumber } catch { try { $osBuild = [int][Environment]::OSVersion.Version.Build } catch { $osBuild = 0 } }
