    Write-WinUtilHost "Windows AI removal components are not applicable on Windows 10 (build $osBuild). Skipping AI package/feature removal steps."
    Write-WinUtilLog -Level 'WARN' -Component 'WindowsAI' -Message "Skipped Windows AI removal steps on Windows 10 build $osBuild."
    return
}

try {
  $sid = $null
  try { $sid = (Get-LocalUser $Env:UserName -ErrorAction SilentlyContinue).Sid.Value } catch { $sid = $null }
  $coreAI = Get-AppxPackage -AllUsers -Name MicrosoftWindows.Client.CoreAI -ErrorAction SilentlyContinue | Select-Object -First 1
  if ($coreAI -and $sid) {
    $eolPath = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Appx\AppxAllUserStore\EndOfLife\$sid\$($coreAI.PackageFullName)"
    try { New-Item -Path $eolPath -Force -ErrorAction SilentlyContinue | Out-Null } catch {}
  }

  $copilotPkgs = Get-AppxPackage -AllUsers -Name '*Copilot*' -ErrorAction SilentlyContinue
  foreach ($pkg in @($copilotPkgs)) {
    try { Remove-AppxPackage -Package $pkg.PackageFullName -AllUsers -ErrorAction Stop; Write-WinUtilLog -Level 'INFO' -Component 'WindowsAI' -Message "Removed AppX package: $($pkg.Name)" } catch { Write-WinUtilLog -Level 'WARN' -Component 'WindowsAI' -Message "Unable to remove AppX package $($pkg.Name): $($_.Exception.Message)" }
  }

  if (Get-Command winget -ErrorAction SilentlyContinue) {
    try { Start-Process -FilePath 'winget' -ArgumentList 'uninstall -e --name "Copilot" --silent --force --accept-source-agreements' -Wait -NoNewWindow -ErrorAction SilentlyContinue | Out-Null } catch {}
  }

  $officeHub = Get-AppxPackage -AllUsers -Name Microsoft.MicrosoftOfficeHub -ErrorAction SilentlyContinue
  foreach ($pkg in @($officeHub)) {
    try { Remove-AppxPackage -Package $pkg.PackageFullName -AllUsers -ErrorAction Stop; Write-WinUtilLog -Level 'INFO' -Component 'WindowsAI' -Message "Removed AppX package: $($pkg.Name)" } catch { Write-WinUtilLog -Level 'WARN' -Component 'WindowsAI' -Message "Unable to remove AppX package $($pkg.Name): $($_.Exception.Message)" }
  }

