    try { Remove-AppxPackage -Package $coreAI.PackageFullName -AllUsers -ErrorAction Stop; Write-WinUtilLog -Level 'INFO' -Component 'WindowsAI' -Message "Removed AppX package: MicrosoftWindows.Client.CoreAI" } catch { Write-WinUtilLog -Level 'WARN' -Component 'WindowsAI' -Message "Unable to remove MicrosoftWindows.Client.CoreAI: $($_.Exception.Message)" }
  }

  if (Get-Service -Name WSAIFabricSvc -ErrorAction SilentlyContinue) {
    try { Set-Service -Name WSAIFabricSvc -StartupType Disabled -ErrorAction Stop } catch { Write-WinUtilLog -Level 'WARN' -Component 'WindowsAI' -Message "Unable to disable WSAIFabricSvc: $($_.Exception.Message)" }
  }

  $recallOutput = powershell.exe -NoProfile -NonInteractive -Command {
    try {
      $f = Get-WindowsOptionalFeature -Online -FeatureName Recall -ErrorAction SilentlyContinue
      if ($null -eq $f) { Write-Output 'Recall feature not present'; exit 0 }
      Disable-WindowsOptionalFeature -FeatureName Recall -Online -NoRestart -ErrorAction Stop | Out-Null
      Write-Output 'Recall disabled'
      exit 0
    } catch {
      Write-Output $_.Exception.Message
      exit 1
