try {
  if (-not (Test-Path -LiteralPath $hostsPath)) {
    New-Item -Path $hostsPath -ItemType File -Force -ErrorAction Stop | Out-Null
  }
  $existing = Get-Content -LiteralPath $hostsPath -Raw -ErrorAction Stop
  if ($null -eq $existing) { $existing = '' }
  if ($existing -match [regex]::Escape($markerStart)) {
    Write-WinUtilHost 'Adobe URL block list is already present in hosts file; skipping.'
    Write-WinUtilLog -Level 'INFO' -Component 'BlockAdobe' -Message 'Adobe block list already present in hosts file.'
    return
  }

  $content = $null
  try {
    $content = Invoke-RestMethod -Uri $hostsUrl -UseBasicParsing -TimeoutSec 30 -ErrorAction Stop
  } catch {
    $msg = "Failed to download Adobe block list: $($_.Exception.Message). Ensure network access to GitHub is available, then retry."
    Write-WinUtilLog -Level 'ERROR' -Component 'BlockAdobe' -Message $msg
    throw $msg
  }

  $text = [string]$content
  if ([string]::IsNullOrWhiteSpace($text)) { throw 'Downloaded Adobe block list was empty.' }
  if ($text.Length -gt 1048576) { throw 'Downloaded Adobe block list is unexpectedly large; refusing to modify hosts file.' }

  $lines = $text -split "`r?`n"
  $valid = 0; $suspicious = 0
  foreach ($line in $lines) {
    $t = $line.Trim()
    if ($t.Length -eq 0) { continue }
    if ($t.StartsWith('#')) { $valid++; continue }
    if ($t -match '^(0\.0\.0\.0|127\.0\.0\.1|::1)\s+\S+') { $valid++; continue }
    if ($t -match '^<') { $suspicious++ }
  }
  if ($valid -lt 1 -or $suspicious -gt 0) {
    throw 'Downloaded Adobe block list did not look like a valid hosts file; refusing to modify hosts file.'
  }

  $trimmed = $text.Trim()
  $prefix = if ($existing.Length -gt 0 -and -not $existing.EndsWith("`n")) { "`r`n" } else { '' }
  $block = "$prefix$markerStart`r`n$trimmed`r`n$markerEnd`r`n"
  Add-Content -LiteralPath $hostsPath -Value $block -Encoding ascii -ErrorAction Stop
  try { ipconfig /flushdns | Out-Null } catch { Write-WinUtilLog -Level 'WARN' -Component 'BlockAdobe' -Message "DNS flush failed after hosts update: $($_.Exception.Message)" }
  Write-WinUtilHost 'Added Adobe URL block list to hosts file.'
  Write-WinUtilLog -Level 'INFO' -Component 'BlockAdobe' -Message 'Added Adobe URL block list to hosts file.'
} catch {
  Write-WinUtilLog -Level 'ERROR' -Component 'BlockAdobe' -Message "Failed to add Adobe block list: $($_.Exception.Message)"
  throw
}

