try {
    # Get all active network adapters and disable the TCPIP6 binding for each
    $adapters = Get-NetAdapter -ErrorAction Stop | Where-Object { $_.Status -eq 'Up' }
    if ($adapters) {
        foreach ($adapter in $adapters) {
            Disable-NetAdapterBinding -InterfaceAlias $adapter.Name -ComponentID ms_tcpip6 -ErrorAction Stop
            Write-WinUtilLog -Level \"INFO\" -Component \"DisableIPv6\" -Message \"Disabled ms_tcpip6 binding on adapter: $($adapter.Name)\"
        }
        Write-WinUtilHost \"IPv6 disabled on all active network adapters.\"
    } else {
        Write-WinUtilHost \"No active network adapters found; skipping binding changes.\"
    }
} catch {
    Write-WinUtilLog -Level \"ERROR\" -Component \"DisableIPv6\" -Message \"Failed to disable IPv6: $($_.Exception.Message)\"
    Write-WinUtilHost \"Failed to disable IPv6.\"
    throw
}

